/**
 * Smoke test: active-studio cookie scoping (S16 P1 regression)
 *
 * Verifies that getAuthenticatedUser() resolves to the studio stored in the
 * `inkos_active_studio` cookie rather than always returning the first-created
 * membership. Without the S16 fix, multi-studio users would see data for
 * studio A regardless of which studio they switched to.
 *
 * Prerequisites (set in .env.test or CI secrets):
 *   NEXT_PUBLIC_SUPABASE_URL       – Supabase project URL
 *   NEXT_PUBLIC_SUPABASE_ANON_KEY  – Supabase anon key
 *   TEST_USER_EMAIL                – test user who belongs to >= 2 studios
 *   TEST_USER_PASSWORD             – test user password
 *   TEST_SECOND_STUDIO_ID          – UUID of the *second* studio (not the first-created one)
 *
 * When TEST_SECOND_STUDIO_ID is absent the test is skipped — safe to run in
 * environments that only have a single studio (e.g. fresh dev setup).
 */
import { test, expect } from './fixtures'

test('cookie-first studio resolution: second studio cookie resolves to second studio', async ({
  signedInPage: page,
}) => {
  const secondStudioId = process.env['TEST_SECOND_STUDIO_ID']

  if (!secondStudioId) {
    // Skipped — single-studio environment. Set TEST_SECOND_STUDIO_ID to enable.
    test.skip()
    return
  }

  // Inject the active-studio cookie pointing to the second studio.
  // This simulates a user having switched studios via the StudioSwitcher.
  await page.context().addCookies([
    {
      name: 'inkos_active_studio',
      value: secondStudioId,
      domain: 'localhost',
      path: '/',
      httpOnly: true,
      secure: false,
      sameSite: 'Lax',
    },
  ])

  // Hit /api/studio/profile — it calls getAuthenticatedUser() and then queries
  // studios WHERE id = auth.studioId. The returned studio.id must equal our cookie.
  const response = await page.request.get('/api/studio/profile')
  expect(response.status()).toBe(200)

  const body = (await response.json()) as { data?: { id?: string } }
  expect(body.data?.id).toBe(secondStudioId)
})

test('fallback: no cookie resolves to first membership', async ({ signedInPage: page }) => {
  // Ensure the cookie is absent so we exercise the fallback path.
  // Playwright clears cookies not set by addCookies, but be explicit.
  const cookies = await page.context().cookies()
  const hasActiveStudio = cookies.some((c) => c.name === 'inkos_active_studio')
  if (hasActiveStudio) {
    await page.context().clearCookies()
    // Re-authenticate after clearing cookies — the signedInPage fixture already ran,
    // so we just navigate to re-inject the session via Supabase anon programmatic path.
    const supabaseUrl = process.env['NEXT_PUBLIC_SUPABASE_URL']
    const supabaseAnonKey = process.env['NEXT_PUBLIC_SUPABASE_ANON_KEY']
    const email = process.env['TEST_USER_EMAIL'] ?? 'smoketest@inkos.dev'
    const password = process.env['TEST_USER_PASSWORD'] ?? 'InkOS_Smoke_2026!'

    if (supabaseUrl && supabaseAnonKey) {
      const res = await fetch(`${supabaseUrl}/auth/v1/token?grant_type=password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', apikey: supabaseAnonKey },
        body: JSON.stringify({ email, password }),
      })
      if (res.ok) {
        const auth = (await res.json()) as { access_token: string; refresh_token: string }
        await page.context().addCookies([
          {
            name: 'sb-access-token',
            value: auth.access_token,
            domain: 'localhost',
            path: '/',
            httpOnly: true,
            secure: false,
            sameSite: 'Lax',
          },
          {
            name: 'sb-refresh-token',
            value: auth.refresh_token,
            domain: 'localhost',
            path: '/',
            httpOnly: true,
            secure: false,
            sameSite: 'Lax',
          },
        ])
      }
    }
  }

  // With no active-studio cookie the API should still return 200 (fallback = first membership).
  const response = await page.request.get('/api/studio/profile')
  expect(response.status()).toBe(200)

  const body = (await response.json()) as { data?: { id?: string } }
  expect(typeof body.data?.id).toBe('string')
  expect(body.data?.id).toBeTruthy()
})
